from pathlib import Path
import json,hashlib,time,importlib.metadata as md
import numpy as np
from PIL import Image,ImageDraw
import torch
from transformers import AutoImageProcessor,AutoModelForDepthEstimation
p=Path(__file__).resolve().parent; source=p.parent/'new-source-20261102/harbor-pavilion-stage/BV1iteRzHEsK_1.093550_4k_preliminary.png';out=p/'harbor-preliminary-analysis';out.mkdir(exist_ok=True)
