# Conservative, manually inspected exclusion ROIs, not instance segmentation or confidence.
mask=Image.new('L',img.size);d=ImageDraw.Draw(mask);d.rectangle((0,1410,3840,2160),fill=4);d.rectangle((1850,940,2170,1530),fill=1);d.rectangle((0,0,900,520),fill=2);d.rectangle((150,1500,1220,2050),fill=2);d.rectangle((1300,1810,2630,2160),fill=2);d.polygon([(1970,250),(2210,690),(2320,950),(2190,1130),(1430,1110),(1610,820),(1790,470)],fill=3);mask.save(out/'manual-exclusion-classes-source-grid.png')
Image.new('L',img.size,255).save(out/'confidence-unknown-source-grid.png')
report={'purpose':'New harbor preliminary source depth analysis ONLY; cropped single frame insufficient for scene modeling or acceptance','source':{'path':str(source),'BV':'BV1iteRzHEsK','part':1,'time_seconds':1.09355,'size':img.size,'bytes':source.stat().st_size,'sha256':sha(source),'crop':[0,0,img.width,img.height],'provenance':'Current source owner manifest: native paused ready4 before/after same time, actual4K; existing login UI; inspected by build owner'},'method':{'repo':'depth-anything/Depth-Anything-V2-Small-hf','revision':json.loads((p/'model-api.json').read_text())['sha'],'license':'apache-2.0','weights_sha256':sha(p/'model/model.safetensors'),'versions':{x:md.version(x) for x in ['torch','transformers','safetensors','pillow','numpy']},'device':'cpu','threads':4,'dtype':'float32','input_tensor_shape':list(x['pixel_values'].shape),'processor_config':json.loads((p/'model/preprocessor_config.json').read_text()),'raw_shape':list(raw.shape),'inference_and_output_seconds':time.time()-t,'trust_remote_code':False,'weights_format':'safetensors','local_files_only':True},'value_definition':'Model relative inverse-depth-like prediction: larger generally nearer, not metric distance, no absolute scale/calibration. Gray white=larger/nearer; black=smaller/farther. Orientation is model convention, not image luminance.','range':{'min':lo,'max':hi,'nonfinite_count':int((~finite).sum())},'normalization':'(raw-min)/(max-min); source-grid derived by bicubic align_corners=False; display clamp to [0,1]. Per-image normalization not cross-image distance.','mask':{'manual-exclusion-classes-source-grid.png':{'0':'unlabelled, NOT certified valid','1':'conservative character bounding rectangle includes nearby background','2':'subtitle screen overlay rectangle','3':'approximate central sky opening polygon; boundary uncertain','4':'conservative lower stage/reflective floor/water or unknown screen region; mixed content, not exact segmentation'},'confidence-unknown-source-grid.png':'255 everywhere means model supplies NO calibrated confidence, not high confidence','reflection_water_transparency_lights':'Reflective stage and horizon/water/ships, translucent-looking mesh bands and sky uncertain. Mask 4 conservatively excludes entire lower mixed region; not source-confirmed water segmentation. Manual masks not exhaustive.','occluded_hidden_geometry':'not measurable from this monocular image; no fabricated completion'},'limitations':['Stylized rendered harbor stage is domain-shifted','No metric truth, hidden geometry, contacts or unique cameras established','A visually plausible map does not validate object geometry','No current source reconstruction or new scene delivered by this test']}
